enum WeatherIcon {
  WI_CLEAR_DAY = 0,
  WI_CLEAR_NIGHT = 1,
  WI_PARTLY_DAY = 2,
  WI_PARTLY_NIGHT = 3,
  WI_CLOUDY = 4,
  WI_FOG = 5,
  WI_RAIN = 6,
  WI_SNOW = 7,
  WI_THUNDER = 8,
  WI_COUNT = 9
};

